#!/usr/bin/env bash
#
# Type checks the QML of the config.
#
# A QML file that does not compile takes down every type that imports it,
# and with it the whole shell. The headless boot cannot see this: it stops
# at the first window before the rest of the config is compiled.
#
# So the files are checked statically instead:
#
#   * qmllint resolves the types, with the "qs" module generated by
#     gen-qs-modules.sh, because Quickshell only builds that module while a
#     shell is running.
#   * a separate pass finds duplicate change signals, which the engine
#     rejects but qmllint does not report for singleton files.
#
# Usage: qml-compile-check.sh [file-or-directory ...]
#        defaults to the whole config.
#
# Every failure is printed as
#
#   <file>: <message>
#
# so that two runs can be compared with each other. The installer uses that
# to tell a new problem apart from one that is already deployed.
#
set -uo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."

QMLLINT=/usr/lib/qt6/bin/qmllint
QML_IMPORTS=/usr/lib/qt6/qml

targets=("$@")
if [[ ${#targets[@]} -eq 0 ]]; then
    targets=(.)
fi

status=0
modules=$(mktemp -d)
quickshell_types=$(mktemp)
files=$(mktemp)
out_file=$(mktemp)
trap 'rm -rf "$modules" "$files" "$out_file" "$quickshell_types"' EXIT

./tests/gen-qs-modules.sh "$modules" > /dev/null

# Files that do not compile. The remaining qmllint warnings are about
# properties that only exist at runtime, for example the dynamic members of
# the Appearance singleton, so they are not failures.
hard_errors='is not a type|was not found|Duplicated signal name|Cannot assign to non-existent property'

# Quickshell exports its own types from the core module and from the
# per-compositor submodules. A submodule sees the types of the core module,
# but the type checker does not, so it reports them as missing. The names are
# taken from the shipped type descriptions, so only names that really do not
# exist anywhere are reported.
find "$QML_IMPORTS/Quickshell" -name '*.qmltypes' -exec cat {} + 2>/dev/null \
    | grep -ohE 'name: "[A-Z][A-Za-z0-9_]*"' \
    | sed 's/name: "//;s/"$//' | sort -u > "$quickshell_types"

for target in "${targets[@]}"; do
    if [[ -d "$target" ]]; then
        find "$target" -name '*.qml' \
            -not -path "$target/.git/*" \
            -not -path "$target/dots/*" >> "$files"
    elif [[ -f "$target" ]]; then
        echo "$target" >> "$files"
    fi
done

# The files are checked in batches: qmllint takes many files at once, and
# starting it once per file is what made this slow.
batches=$(mktemp -d)
trap 'rm -rf "$modules" "$files" "$out_file" "$quickshell_types" "$batches"' EXIT
split -l 40 "$files" "$batches/batch_"

ls "$batches" | xargs -P "$(nproc)" -I '{}' sh -c '
    out=$('"$QMLLINT"' -I . -I '"$modules"' -I '"$QML_IMPORTS"' $(cat "'"$batches"'/{}") 2>&1 \
        | grep -E "'"$hard_errors"'")
    [ -n "$out" ] && echo "$out"
' > "$out_file"

if [[ -s "$out_file" ]]; then
    while IFS= read -r line; do
        # Drop the warnings about types that Quickshell itself exports.
        name=$(printf '%s' "$line" | sed -nE 's/.*: ([A-Za-z0-9_]+) was not found.*/\1/p')
        if [[ -n "$name" ]] && grep -qx "$name" "$quickshell_types"; then
            continue
        fi
        status=1
        # "Warning: file:line:column: message" -> "file: message"
        printf '%s\n' "$line" \
            | sed -E 's/^(Warning|Error): ([^:]+):[0-9]+(:[0-9]+)?: (.*)$/\2: \4/'
    done < "$out_file"
fi

# Duplicate change signals: the engine rejects these, qmllint does not
# report them for singleton files.
dup=$(python3 ./tests/check-duplicate-signals.py "${targets[@]}" 2>&1)
if [[ -n "$dup" ]]; then
    status=1
    # "file:line: message" -> "file: message"
    printf '%s\n' "$dup" | sed -E 's/^([^:]+):[0-9]+: /\1: /'
fi

if [[ $status -eq 0 ]]; then
    echo "PASS: the QML compiles"
fi
exit $status
